<script setup lang="ts">
import {useProductivityStore} from '~/stores/productivity'; const store=useProductivityStore(); const route=useRoute(); const now=ref(Date.now()); let tick:any; const custom=ref(store.settings.customTimerDefault); const note=ref(''); const rating=ref(4)
onMounted(()=>tick=setInterval(()=>now.value=Date.now(),500)); onBeforeUnmount(()=>clearInterval(tick))
const timer=computed(()=>store.activeTimer); const elapsed=computed(()=>{const t=timer.value;if(!t)return 0;return t.elapsedBeforePause+(t.status==='running'?Math.floor((now.value-t.startedAt)/1000):0)}); const remaining=computed(()=>Math.max(0,(timer.value?.durationSeconds||0)-elapsed.value)); const display=computed(()=>{const s=remaining.value;return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}); const linked=computed(()=>store.tasks.find(t=>t.id===route.query.taskId)||store.tasks.find(t=>t.id===timer.value?.taskId));
watch(remaining,(v)=>{if(v===0&&timer.value?.status==='running')finish(true)})
const start=(mins:number,mode:'focus'|'custom'|'schedule'='focus')=>{const task=linked.value;store.startTimer({label:task?.title||'تمرکز آزاد',durationSeconds:mins*60,taskId:task?.id,mode})}
const finish=(auto=false)=>{const t=timer.value;if(!t)return;const mins=Math.max(1,Math.round(elapsed.value/60));store.logFocusSession({taskId:t.taskId,label:t.label,mode:t.mode,plannedMinutes:Math.round(t.durationSeconds/60),actualMinutes:mins,startedAt:new Date(t.startedAt).toISOString(),endedAt:new Date().toISOString(),interruptions:0,distractions:[],focusRating:rating.value,note:note.value||undefined});if(t.taskId&&auto)store.toggleTask(t.taskId);store.clearTimer();note.value=''}
</script>
<template><div class="max-w-4xl mx-auto space-y-5"><div><h1 class="text-2xl font-black">مرکز اجرا و تایمر</h1><p class="text-gray-500">تایمر در localStorage ذخیره می‌شود؛ رفرش صفحه آن را از صفر نمی‌کند.</p></div><UCard><div class="flex flex-wrap gap-2 justify-center mb-8"><UButton v-for="p in store.settings.timerPresets" :key="p" :disabled="!!timer" variant="soft" @click="start(p)">{{p}} دقیقه</UButton></div><div class="text-center"><div class="text-8xl md:text-9xl font-black timer-number">{{display}}</div><p class="text-gray-500 mt-3">{{timer?.label||linked?.title||'تمرکز آزاد'}}</p><div class="flex justify-center gap-2 mt-8 flex-wrap"><UButton v-if="!timer" size="xl" icon="i-lucide-play" @click="start(custom,'custom')">شروع {{custom}} دقیقه</UButton><UButton v-else-if="timer.status==='paused'" size="xl" @click="store.resumeTimer">ادامه</UButton><UButton v-else size="xl" icon="i-lucide-pause" @click="store.pauseTimer">توقف موقت</UButton><UButton v-if="timer" color="success" size="xl" icon="i-lucide-check" @click="finish(false)">پایان و ثبت</UButton><UButton v-if="timer" color="error" variant="ghost" @click="store.clearTimer">لغو</UButton></div><div v-if="!timer" class="max-w-xs mx-auto mt-6"><UFormField label="تایمر دلخواه (دقیقه)"><UInput v-model.number="custom" type="number" min="1"/></UFormField></div></div></UCard><UCard v-if="timer"><template #header>ثبت نتیجه</template><div class="grid md:grid-cols-2 gap-4"><UFormField label="کیفیت تمرکز"><USlider v-model="rating" :min="1" :max="5" :step="1"/></UFormField><UTextarea v-model="note" placeholder="یادداشت این جلسه"/></div></UCard><UAlert color="primary" variant="soft" title="نکته" description="اگر برنامه‌ات زمان‌بندی شده باشد، از صفحه «امروز» دکمه اجرا را بزن تا کار و تایمر به هم متصل شوند."/></div></template>
